const fs = require("fs")
const path = require("path")

// Load link-map.json at startup (generated by prebuild script)
const linkMapPath = path.join(__dirname, "src", "lib", "link-map.json")
let activeLinks = new Set()

function loadActiveLinks() {
  if (fs.existsSync(linkMapPath)) {
    const { active } = JSON.parse(fs.readFileSync(linkMapPath, "utf-8"))
    activeLinks = new Set(active)
    console.log(`[gatsby-node] Loaded ${activeLinks.size} active links`)
  } else {
    console.warn("[gatsby-node] link-map.json not found, building all pages")
    activeLinks = null // null means build all
  }
}

loadActiveLinks()

exports.onCreatePage = ({ page, actions }) => {
  const { createPage } = actions

  // If no active links loaded, build all pages
  if (activeLinks === null) {
    const newPage = Object.assign({}, page)
    newPage.path = "en" + page.path
    createPage(page)
    createPage(newPage)
    return
  }

  // Skip if page is not active
  if (!page.path || page.path === "/") {
    const newPage = Object.assign({}, page)
    newPage.path = "en" + page.path
    createPage(page)
    createPage(newPage)
    return
  }

  const pathStr = page.path.replace(/^\//, "").replace(/\/$/, "")
  const url = "/" + pathStr + "/"

  if (!activeLinks.has(url)) {
    return // Skip unpublished page
  }

  const newPage = Object.assign({}, page)
  newPage.path = "en" + page.path
  createPage(page)
  createPage(newPage)
}

exports.onCreateWebpackConfig = ({ stage, actions, getConfig, plugins }) => {
  const PATTERN = /\.(eot|otf|ttf|woff(2)?)(\?.*)?$/

  const config = getConfig()
  if (stage === "build-javascript" && process.env.CIRCLECI === "true") {
    console.log("DETECTED CIRCLE-CI - SETTING TERSER PARALLEL TO 8")
    config.optimization.minimizer[0].options.parallel = 8
  } else {
    console.log(`DID NOT DETECT CIRCLE-CI => process.env.CIRCLECI=${process.env.CIRCLECI}`)
  }

  if (stage === "build-javascript" || stage === "develop") {
    config.plugins.push(plugins.provide({ process: "process/browser" }))
  }

  const newConfig = {
    ...config,
    resolve: {
      ...config.resolve,
      alias: {
        ...config.resolve.alias,
        path: require.resolve("path-browserify"),
      },
    },
    module: {
      rules: config.module.rules.map((rule) => {
        if (rule.test && rule.test.toString() === PATTERN.toString()) {
          rule.use[0].options.limit = 1
          rule.use[0].options.name = `static/fonts/[name]-[hash].[ext]`
        }
        return rule
      }),
    },
  }

  actions.replaceWebpackConfig(newConfig)
}